use vstd::prelude::*;
verus! {

    /// Given a non-empty vector of characters `t`, return a new vector of the
    /// same length whose contents are exactly the characters of `t` in order.
    ///
    /// We prove:
    ///  1. The output has the same length as the input.
    ///  2. For every index `i` in `0..t.len()`, the `i`-th element of the
    ///     result equals the `i`-th element of `t`.
    ///
    /// We also show termination via a strictly decreasing measure
    /// `t.len() - i`.
    fn solve(mut t: Vec<char>) -> Vec<char>
        requires
            // input is non‐empty
            t.len() >= 1,
        ensures
            // output has same length as input
            result.len() == t.len(),
        ensures
            // element‐wise equality
            forall |i: usize| i < t.len() ==> result[i] == t[i],
    {
        // We'll build up `res` by pushing one character at a time.
        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // Loop invariant:
        //   1. 0 ≤ i ≤ t.len()
        //   2. res.len() == i
        //   3. for all j < i, res[j] == t[j]
        //
        // Decreases measure: t.len() - i
        //   This is strictly decreasing each iteration, and non‐negative.
        while i < t.len()
            invariant
                i <= t.len(),
            invariant
                res.len() == i,
            invariant
                forall |j: usize| j < i ==> res[j] == t[j],
            decreases
                t.len() - i
        {
            // append the next character
            res.push(t[i]);
            i = i + 1;
        }

        res
    }
}